#pragma once
namespace brooklyn::wifi {
constexpr char kSetupCss[]=R"CSS(
body.setup-shell{max-width:760px}.setup-shell main{display:block}.setup-shell header{margin-bottom:18px}.setup-shell .hero{border-top:4px solid #1d67b8}.setup-shell .hero h2{font-size:28px}.setup-shell section{margin-bottom:16px}.steps{display:flex;gap:8px;list-style:none;padding:0;margin:18px 0}.steps li{flex:1;border-top:3px solid #dce4ef;padding-top:8px;color:#52647b;font-size:13px}.steps li[aria-current=step]{border-color:#184b96;color:#184b96;font-weight:700}.step-title{display:flex;align-items:center;gap:10px}.step-number{display:grid;place-items:center;flex-shrink:0;width:30px;height:30px;background:#edf3fb;color:#184b96;border-radius:50%;font-size:15px}.alert{padding:16px;border-radius:10px;background:#edf3fb;border-left:4px solid #184b96;margin:14px 0}.alert.error{background:#fff1f1;border-color:#b8323c}.alert.success{background:#edf8f0;border-color:#267344}.alert.warning{background:#fff8e7;border-color:#a66c00}.network-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;max-height:300px;overflow:auto;margin:14px 0}.network{display:block;min-width:0;width:100%;text-align:left;background:white;color:#192b44;border:1px solid #dce4ef;padding:12px}.network.selected{border:2px solid #184b96;background:#edf3fb;padding:11px}.network .ssid{display:block;overflow-wrap:anywhere}.network small{display:block;color:#52647b;font-weight:400;margin-top:4px}.setup-shell form{gap:14px}.setup-shell .submit{width:100%;justify-self:stretch}.setup-shell .check{display:flex;align-items:center;gap:2px;font-weight:400;font-size:14px}.setup-shell .check input{flex-shrink:0}.setup-shell .actions{align-items:center}.setup-shell .pill{display:inline-block;padding:4px 10px;background:#edf8f0;color:#24633b;border-radius:20px;font-size:13px}.setup-shell progress{width:100%;height:12px}.setup-shell .ip-link{font-size:22px;overflow-wrap:anywhere}.setup-shell .footer{padding:8px}.setup-shell label{overflow-wrap:anywhere}@media(max-width:480px){.network-list{grid-template-columns:1fr;max-height:260px}.steps{gap:6px}.steps li{font-size:12px}.setup-shell .hero h2{font-size:25px}.setup-shell section{padding:18px}}
)CSS";
constexpr char kSetupScript[]=R"JS((()=>{const form=document.getElementById('wifi-form');document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',()=>{const b=f.querySelector('button[type=submit]');if(b){b.dataset.original=b.textContent;b.disabled=true;b.textContent=f.id==='wifi-form'?'Connecting...':'Saving...'}}));addEventListener('pageshow',()=>document.querySelectorAll('button[data-original]').forEach(b=>{b.textContent=b.dataset.original;b.disabled=false}));if(!form)return;const field=document.getElementById('wifi-name'),password=document.getElementById('wifi-password'),list=document.getElementById('setup-networks'),note=document.getElementById('scan-state'),scan=document.getElementById('scan-again');let timer=null,inflight=false;function select(button){const name=button.querySelector('.ssid').textContent;if(field.value!==name)password.value='';field.value=name;field.dispatchEvent(new Event('input',{bubbles:true}));list.querySelectorAll('button').forEach(b=>{const selected=b===button;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected?'true':'false')});password.focus()}function wire(){list.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>select(b)))}wire();field.addEventListener('input',()=>list.querySelectorAll('button').forEach(b=>{const selected=b.querySelector('.ssid').textContent===field.value;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected?'true':'false')}));async function load(rescan=false){if(inflight)return;inflight=true;scan.disabled=true;let abort;try{const c=new AbortController();abort=setTimeout(()=>c.abort(),6000);const r=await fetch('/setup/networks'+(rescan?'?rescan=1':''),{cache:'no-store',signal:c.signal});if(!r.ok)throw Error();const s=await r.json();const fragment=document.createDocumentFragment();s.networks.forEach(e=>{const b=document.createElement('button');b.type='button';b.className='network';const name=document.createElement('span');name.className='ssid';name.textContent=e.ssid;const info=document.createElement('small');info.textContent=(e.rssi>=-60?'Strong signal':e.rssi>=-75?'Good signal':'Weak signal')+' - '+(e.encrypted?'Password needed':'Open network');b.append(name,info);const selected=field.value===e.ssid;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected?'true':'false');fragment.append(b)});const scroll=list.scrollTop;list.replaceChildren(fragment);list.scrollTop=scroll;wire();note.textContent=s.pending?'Looking for nearby Wi-Fi...':s.networks.length?'Choose a network above, or type its name below.':'No networks found yet. Try scanning again, or type the Wi-Fi name below.';scan.disabled=s.pending||s.busy;if(s.pending)timer=setTimeout(()=>load(),1200);}catch(e){note.textContent='Could not load nearby networks. You can type the Wi-Fi name below or try Scan again.';scan.disabled=false;}finally{clearTimeout(abort);inflight=false}}scan.addEventListener('click',()=>{clearTimeout(timer);load(true)});load()})();)JS";
}
